                    "text": "اللَّهُمَّ اهْدِنَا فِيمَنْ هَدَيْتَ، وَعَافِنَا فِيمَنْ عَافَيْتَ، وَتَوَلَّنَا فِيمَنْ تَوَلَّيْتَ، وَبَارِكْ لَنَا فِيمَا أَعْطَيْتَ، وَقِنَا شَرَّ مَا قَضَيْتَ، إِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ، إِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، وَلَا يَعِزُّ مَنْ عَادَيْتَ، تَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ.",
                    "latin": "Allāhumma ihdinā fīman hadayt, wa-ʿāfinā fīman ʿāfayt, wa-tawallanā fīman tawallayt, wa-bārik lanā fīmā aʿṭayt, wa-qinā sharra mā qaḍayt. Innaka taqḍī wa-lā yuqḍā ʿalayk. Innahu lā yadhillu man wālayt, wa-lā yaʿizzu man ʿādayt. Tabārakta rabbanā wa-taʿālayt.",
                    "explanationEs": "Oh Allah, guíanos junto a quienes has guiado; concédenos bienestar junto a quienes se lo has concedido; sé nuestro protector junto a quienes has protegido. Bendice lo que nos has concedido y protégenos del mal de lo que has decretado. Tú decretas y nadie decreta sobre Ti. No queda humillado quien está bajo Tu protección, ni alcanza honor quien se opone a Ti. Bendito y exaltado seas, Señor nuestro.",
