                    "text": "قَالَ عَمَّارُ بْنُ يَاسِرٍ رَضِيَ اللَّهُ عَنْهُ: \nثَلَاثٌ مَنْ جَمَعَهُنَّ فَقَدْ جَمَعَ الْإِيمَانَ: الْإِنْصَافُ مِنْ نَفْسِكَ، وَبَذْلُ السَّلَامِ لِلْعَالَمِ، وَالْإِنْفَاقُ مِنَ الْإِقْتَارِ.",
                    "latin": "Qāla ʿAmmāru bnu Yāsirin raḍiya Allāhu ʿanhu: thalāthun man jamaʿahunna faqad jamaʿa al-īmān: al-inṣāfu min nafsik, wa-badhl as-salāmi li-l-ʿālam, wa-l-infāqu mina al-iqtār.",
                    "explanationEs": "ʿAmmār ibn Yāsir, que Allah esté complacido con él, dijo: «Tres cualidades reúnen la fe: ser justo incluso contigo mismo, ofrecer el saludo de paz a todos y dar incluso cuando se tienen pocos recursos».",
